// ===========================================================================
// Validacion aritmetica de la factura.
// El template #6480 escribe en Sheets lo que sea que le devuelva el LLM.
// Este nodo se para en el medio y pregunta: ¿los numeros cierran?
// ===========================================================================

const TOLERANCIA = 0.01;  // un centavo. Mas que eso no es redondeo, es error.

// Severidad por tipo de problema. 'alta' manda la factura a revision humana.
const SEVERIDAD = {
  CAMPO_FALTANTE:     'alta',
  SIN_ITEMS:          'alta',
  ITEM_NO_CIERRA:     'alta',
  SUBTOTAL_NO_CIERRA: 'alta',
  TOTAL_NO_CIERRA:    'alta',
  TOTAL_VS_ITEMS:     'alta',
  TOTAL_NO_POSITIVO:  'alta',
  IA_ALTERO_EL_DATO:  'alta',
  ITEM_SIN_IMPORTE:   'media',
  FECHA_INVALIDA:     'media',
  FECHA_FUERA_RANGO:  'media',
  MONEDA_DESCONOCIDA: 'media',
};

const MONEDAS = ['ARS', 'USD', 'EUR', 'BRL', 'CLP', 'UYU', 'MXN', 'GBP', 'DKK'];

const r2 = (n) => Math.round(n * 100) / 100;

// El LLM devuelve numeros en el formato del documento: 1.234,56 o 1,234.56.
// Decidir cual es cual mirando que separador aparece ultimo.
function num(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return isFinite(v) ? v : null;
  let s = String(v).replace(/[^0-9.,-]/g, '').trim();
  if (!s) return null;
  const coma = s.lastIndexOf(',');
  const punto = s.lastIndexOf('.');
  if (coma > punto) s = s.replace(/\./g, '').replace(',', '.');
  else s = s.replace(/,/g, '');
  const n = parseFloat(s);
  return isFinite(n) ? n : null;
}

// DD/MM/YYYY, DD.MM.YYYY, YYYY-MM-DD. Todas aparecen en las facturas reales.
function fecha(v) {
  const s = String(v ?? '').trim();
  let m;
  if ((m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/))) return new Date(+m[1], +m[2] - 1, +m[3]);
  if ((m = s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})$/))) return new Date(+m[3], +m[2] - 1, +m[1]);
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

// El Information Extractor devuelve SOLO los campos del schema: el nombre del
// archivo se pierde en el camino. Hay que ir a buscarlo al trigger.
// itemMatching sigue la trazabilidad del item aunque el IF haya partido el
// flujo; el acceso por indice cubre el caso de una sola factura por corrida,
// que es como se graba el episodio.
function nombreArchivo(indice) {
  try { return $('Drive — Nueva factura').itemMatching(indice).json.name; } catch (e) {}
  try { return $('Drive — Nueva factura').all()[indice].json.name; } catch (e) {}
  return '(sin nombre)';
}

// ===========================================================================
// AUDITORIA DE LA EXTRACCION — por que existe este bloque
//
// En la factura 06 el PDF declara "Subtotal 702.000,00 / IVA 147.420,00 /
// TOTAL 849.420,00". gpt-5-mini vio que los items sumaban 720.000, dedujo que
// el subtotal estaba mal tipeado y devolvio 720.000 / 151.200 / 871.200:
// reparo el documento en transito. El validador solo veia la salida del
// modelo, recibio una factura internamente coherente, no tuvo contra que
// comparar y la marco OK. Cero problemas, cero alerta.
//
// Endurecer el prompt NO alcanzo. Se le pidio explicitamente, en mayusculas y
// con la razon, que no corrigiera, y volvio a corregir. Un prompt es una
// sugerencia, no un candado: si hace falta una garantia dura, tiene que estar
// en codigo determinista.
//
// La unica fuente de verdad es el texto del PDF, que es lo que el modelo tuvo
// enfrente. Se contrasta en dos capas:
//   1. Recuperacion: se busca el monto real por su etiqueta y se usa ESE.
//   2. Red de seguridad: si la etiqueta no se pudo leer, al menos se verifica
//      que el numero del modelo figure en algun lado del documento.
// La capa 2 no recupera el valor, pero marca la factura igual. Nunca quedamos
// peor que antes de auditar.
// ===========================================================================

function textoDelPdf(indice) {
  try { return String($('PDF — Extraer texto').itemMatching(indice).json.text ?? ''); } catch (e) {}
  try { return String($('PDF — Extraer texto').all()[indice].json.text ?? ''); } catch (e) {}
  return '';
}

// Una linea de totales es corta y termina en el importe, con o sin simbolo de
// moneda detras. Los dos filtros importan: sin ellos, en la factura 02 la
// etiqueta /vat/ engancha el pie legal "...under Article 196 of Council
// Directive 2006/112/EC" y devuelve 112 como si fuera el IVA.
const LARGO_MAXIMO_LINEA = 60;
const IMPORTE_AL_FINAL = /(-?\d[\d.,]*)\s*(?:[A-Z]{0,3}|[$€£])\s*$/;

// Se recorre linea por linea en vez de armar un regex unico porque las
// facturas vienen en tres idiomas y con la etiqueta pegada o separada del
// importe. Se toma la ULTIMA coincidencia porque el bloque de totales va al
// pie del documento, mientras que el CUIT o el VAT number del emisor —que
// tambien matchean la etiqueta— van en el encabezado.
function montoTrasEtiqueta(texto, etiqueta, excluir) {
  let encontrado = null;
  for (const cruda of texto.split(/\r?\n/)) {
    const linea = cruda.trim();
    if (!linea || linea.length > LARGO_MAXIMO_LINEA) continue;
    if (!etiqueta.test(linea)) continue;
    if (excluir && excluir.test(linea)) continue;
    const m = linea.match(IMPORTE_AL_FINAL);
    if (!m) continue;
    const v = num(m[1]);
    if (v !== null) encontrado = v;
  }
  return encontrado;
}

// Todos los numeros que figuran en el documento. Sirve para preguntar "¿este
// valor esta escrito en algun lado del PDF?" sin depender de etiquetas ni del
// formato de separadores, que cambia entre las facturas ARS, USD y EUR.
function numerosDelTexto(texto) {
  const set = new Set();
  for (const t of (texto.match(/-?\d[\d.,]*/g) || [])) {
    const v = num(t);
    if (v !== null) set.add(r2(v));
  }
  return set;
}

const RE_SUBTOTAL    = /subtotal|zwischensumme|nettobetrag|importe neto|net total/i;
const RE_TOTAL       = /\b(total|gesamtbetrag|rechnungsbetrag|amount due|importe total)\b/i;
const RE_NO_SUBTOTAL = /subtotal|zwischensumme/i;
const RE_IMPUESTO    = /\b(iva|vat|mwst|ust|impuesto|impuestos|tax)\b/i;

const salida = [];
const entradas = $input.all();

for (let idx = 0; idx < entradas.length; idx++) {
  const entrada = entradas[idx];
  // El Information Extractor de n8n no devuelve los campos en la raiz: los
  // anida bajo 'output'. Leyendo entrada.json directo, TODOS los campos dan
  // undefined y el validador reporta como vacia una factura que se extrajo
  // perfecto. Es el bug que llenaba la planilla de CAMPO_FALTANTE.
  const bruto = entrada.json ?? {};
  const f = (bruto.output && typeof bruto.output === 'object') ? bruto.output : bruto;
  const problemas = [];
  const avisar = (tipo, detalle, extra) => problemas.push(
    Object.assign({ tipo, severidad: SEVERIDAD[tipo] ?? 'media', detalle }, extra || {})
  );

  // --- 1. Campos sin los cuales la factura no sirve para nada -------------
  const requeridos = ['numero_factura', 'emisor', 'fecha_emision', 'moneda', 'total'];
  for (const campo of requeridos) {
    const v = f[campo];
    if (v === null || v === undefined || String(v).trim() === '') {
      avisar('CAMPO_FALTANTE', 'No se pudo extraer el campo "' + campo + '"', { campo });
    }
  }

  // --- 2. ¿Los items suman lo que dice el subtotal? -----------------------
  const items = Array.isArray(f.items) ? f.items : [];
  if (items.length === 0) avisar('SIN_ITEMS', 'No se extrajo ningun item de detalle');

  let sumaItems = 0;
  items.forEach((it, i) => {
    const importe = num(it.importe);
    if (importe === null) {
      avisar('ITEM_SIN_IMPORTE', 'Item ' + (i + 1) + ': importe ilegible');
      return;
    }
    sumaItems += importe;

    // Cada item tambien tiene que cerrar consigo mismo.
    const cant = num(it.cantidad);
    const unit = num(it.precio_unitario);
    if (cant !== null && unit !== null) {
      const esperado = r2(cant * unit);
      if (Math.abs(esperado - importe) > TOLERANCIA) {
        avisar('ITEM_NO_CIERRA',
          'Item ' + (i + 1) + ': ' + cant + ' x ' + unit + ' = ' + esperado + ', pero declara ' + importe,
          { diferencia: r2(importe - esperado) });
      }
    }
  });
  sumaItems = r2(sumaItems);

  // --- 2b. Auditoria: contrastar lo extraido contra el texto del PDF ------
  const textoPdf = textoDelPdf(idx);
  const numerosPdf = textoPdf ? numerosDelTexto(textoPdf) : null;

  // Devuelve el valor que hay que usar de aca en adelante: el del PDF si se
  // pudo recuperar, el del modelo si no. Avisa cuando difieren.
  const auditar = (campo, valorLLM, etiqueta, excluir) => {
    if (!textoPdf || valorLLM === null) return valorLLM;
    const valorPdf = montoTrasEtiqueta(textoPdf, etiqueta, excluir);
    if (valorPdf !== null) {
      if (Math.abs(valorPdf - valorLLM) > TOLERANCIA) {
        avisar('IA_ALTERO_EL_DATO',
          'La IA devolvio ' + valorLLM + ' como ' + campo + ' pero el PDF dice ' + valorPdf +
          '. Se usa el del PDF.',
          { campo: campo, valor_ia: valorLLM, valor_pdf: valorPdf,
            diferencia: r2(valorLLM - valorPdf) });
      }
      return valorPdf;
    }
    // Red de seguridad: la etiqueta no se pudo leer, pero el numero que
    // devolvio el modelo no figura en ninguna parte del documento. No se puede
    // recuperar el valor real; lo que no se puede es dejarla pasar como buena.
    if (numerosPdf && !numerosPdf.has(r2(valorLLM))) {
      avisar('IA_ALTERO_EL_DATO',
        'La IA devolvio ' + valorLLM + ' como ' + campo + ' y ese numero no figura en el PDF.',
        { campo: campo, valor_ia: valorLLM, valor_pdf: null });
    }
    return valorLLM;
  };

  // Los identificadores duros no se recalculan: se verifican por presencia
  // literal. En una corrida real el modelo devolvio "0004-00012847" como
  // numero de la factura 06 —que es el comprobante de la factura 01— mientras
  // el PDF decia "0003-00008816". Ningun chequeo aritmetico agarra eso: los
  // montos cerraban. Una factura imputada al comprobante equivocado se paga
  // dos veces y la conciliacion nunca cierra.
  const textoPlano = textoPdf.replace(/\s+/g, '').toLowerCase();
  if (textoPlano) {
    for (const campo of ['numero_factura', 'cuit_emisor']) {
      const valor = String(f[campo] ?? '').trim();
      if (!valor) continue;
      const aguja = valor.replace(/\s+/g, '').toLowerCase();
      if (aguja.length >= 4 && !textoPlano.includes(aguja)) {
        avisar('IA_ALTERO_EL_DATO',
          'La IA devolvio "' + valor + '" como ' + campo + ' y ese valor no figura en el PDF.',
          { campo: campo, valor_ia: valor, valor_pdf: null });
      }
    }
  }

  const subtotal = auditar('subtotal', num(f.subtotal), RE_SUBTOTAL);
  if (subtotal !== null && items.length > 0 && Math.abs(sumaItems - subtotal) > TOLERANCIA) {
    avisar('SUBTOTAL_NO_CIERRA',
      'Los items suman ' + sumaItems + ' pero la factura declara un subtotal de ' + subtotal,
      { suma_items: sumaItems, subtotal_declarado: subtotal, diferencia: r2(sumaItems - subtotal) });
  }

  // --- 3. ¿subtotal + impuestos da el total? ------------------------------
  const lineasImpuesto = (Array.isArray(f.impuestos) ? f.impuestos : [])
    .map((t) => num(t && t.importe))
    .filter((n) => n !== null);
  let impuestos = r2(lineasImpuesto.reduce((a, b) => a + b, 0));
  // Solo se audita contra el PDF cuando hay UNA sola linea de impuesto. Con
  // varias (IVA + percepciones), la etiqueta devuelve una sola y compararla
  // contra la suma daria un falso positivo.
  if (lineasImpuesto.length === 1) {
    impuestos = auditar('impuestos', impuestos, RE_IMPUESTO);
  }
  const total = auditar('total', num(f.total), RE_TOTAL, RE_NO_SUBTOTAL);
  const base = subtotal !== null ? subtotal : sumaItems;

  // Los impuestos declarados se liquidaron SOBRE EL SUBTOTAL DECLARADO. Si ese
  // subtotal esta mal, arrastrarlos tal cual subestima el agujero: en la 06 da
  // 18.000 cuando lo que realmente falta son 21.780. Hay que reliquidarlos
  // sobre la suma real de los items.
  //
  // La alicuota sale de los propios numeros del documento (impuestos/subtotal),
  // NO de parsear "IVA 21%" del texto. Parsear el string es fragil: se rompe
  // con otras alicuotas, con percepciones sumadas y con los idiomas del resto
  // de las facturas. La razon declarada funciona en todos esos casos, y en una
  // factura sin impuestos da 0, que es lo correcto.
  let impuestosReales = impuestos;
  if (items.length > 0 && subtotal !== null && Math.abs(subtotal) > TOLERANCIA) {
    impuestosReales = r2(sumaItems * (impuestos / subtotal));
  }
  const totalRecalculado = items.length > 0 ? r2(sumaItems + impuestosReales) : null;

  if (total !== null) {
    // 3a. Coherencia interna del documento.
    const esperado = r2(base + impuestos);
    if (Math.abs(esperado - total) > TOLERANCIA) {
      avisar('TOTAL_NO_CIERRA',
        base + ' + ' + r2(impuestos) + ' de impuestos = ' + esperado + ', pero el total dice ' + total,
        { total_declarado: total, total_calculado: esperado, diferencia: r2(total - esperado) });
    }
    // 3b. El chequeo que realmente importa: recalcular DESDE LOS ITEMS.
    //     Si el subtotal viene mal tipeado, 3a pasa igual porque el IVA y el
    //     total se calcularon sobre el subtotal equivocado. Solo re-sumando
    //     los items se ve el agujero.
    if (totalRecalculado !== null && Math.abs(totalRecalculado - total) > TOLERANCIA) {
      avisar('TOTAL_VS_ITEMS',
        'Reliquidado desde los items el total seria ' + totalRecalculado + ', la factura dice ' + total,
        { total_declarado: total, total_recalculado: totalRecalculado,
          diferencia: r2(total - totalRecalculado) });
    }
    if (total <= 0) avisar('TOTAL_NO_POSITIVO', 'El total es ' + total);
  }

  // --- 4. Sanidad de fecha y moneda ---------------------------------------
  const emision = fecha(f.fecha_emision);
  if (f.fecha_emision && emision === null) {
    avisar('FECHA_INVALIDA', 'No se pudo interpretar la fecha "' + f.fecha_emision + '"');
  } else if (emision) {
    const hoy = new Date();
    const dias = (hoy - emision) / 86400000;
    if (dias < -1) avisar('FECHA_FUERA_RANGO', 'La fecha de emision esta en el futuro');
    else if (dias > 730) avisar('FECHA_FUERA_RANGO', 'La factura tiene mas de 2 años');
  }

  const moneda = String(f.moneda ?? '').trim().toUpperCase();
  if (moneda && !MONEDAS.includes(moneda)) {
    avisar('MONEDA_DESCONOCIDA', 'Moneda no reconocida: "' + moneda + '"');
  }

  // --- 5. Veredicto -------------------------------------------------------
  const hayGraves = problemas.some((p) => p.severidad === 'alta');
  const estado = problemas.length === 0 ? 'OK' : (hayGraves ? 'REVISAR' : 'ADVERTENCIA');

  salida.push({
    json: {
      archivo: nombreArchivo(idx),
      numero_factura: f.numero_factura ?? null,
      emisor: f.emisor ?? null,
      cuit_emisor: f.cuit_emisor ?? null,
      fecha_emision: f.fecha_emision ?? null,
      fecha_vencimiento: f.fecha_vencimiento ?? null,
      moneda: moneda || null,
      cantidad_items: items.length,
      suma_items: sumaItems,
      subtotal_declarado: subtotal,
      impuestos_total: r2(impuestos),
      // Se expone reliquidado adems de declarado para que la planilla cierre
      // sola en pantalla: suma_items + impuestos_recalculado = total_recalculado,
      // igual que subtotal_declarado + impuestos_total = total_declarado.
      // Sin esta columna, hacer la cuenta en camara desde la planilla no da.
      impuestos_recalculado: items.length > 0 ? impuestosReales : null,
      total_declarado: total,
      total_recalculado: totalRecalculado,
      estado: estado,
      requiere_revision: estado !== 'OK',
      cantidad_problemas: problemas.length,
      problemas: problemas,
      resumen_problemas: problemas.map((p) => p.tipo).join(', ') || 'ninguno',
      procesado_en: new Date().toISOString(),
      items: items,
    },
  });
}

return salida;

// ===========================================================================
// El PDF no trae capa de texto: es un escaneo.
// El template original manda igual el string vacio al LLM, que inventa algo o
// devuelve nulls, y eso termina en la planilla como si fuera un dato.
// Aca se corta antes y se marca para revision.
// ===========================================================================

function nombreArchivo(indice) {
  try { return $('Drive — Nueva factura').itemMatching(indice).json.name; } catch (e) {}
  try { return $('Drive — Nueva factura').all()[indice].json.name; } catch (e) {}
  return '(sin nombre)';
}

const salida = [];
const entradas = $input.all();

for (let idx = 0; idx < entradas.length; idx++) {
  const entrada = entradas[idx];
  const largo = String(entrada.json.text ?? '').trim().length;

  salida.push({
    json: {
      archivo: nombreArchivo(idx),
      numero_factura: null,
      emisor: null,
      cuit_emisor: null,
      fecha_emision: null,
      fecha_vencimiento: null,
      moneda: null,
      cantidad_items: 0,
      suma_items: null,
      subtotal_declarado: null,
      impuestos_total: null,
      impuestos_recalculado: null,
      total_declarado: null,
      total_recalculado: null,
      estado: 'REVISAR',
      requiere_revision: true,
      cantidad_problemas: 1,
      problemas: [{
        tipo: 'SIN_CAPA_DE_TEXTO',
        severidad: 'alta',
        detalle: 'El PDF no tiene texto extraible (' + largo + ' caracteres). ' +
                 'Es un escaneo: hace falta OCR antes de poder leerlo.',
      }],
      resumen_problemas: 'SIN_CAPA_DE_TEXTO',
      procesado_en: new Date().toISOString(),
      items: [],
    },
  });
}

return salida;

// ===========================================================================
// Explota la factura en una fila por item para la pestaña de detalle.
//
// La cabecera (EP4_FACTURAS) responde "¿esta factura cierra?".
// El detalle  (EP4_ITEMS)    responde "¿que se compro y a que precio?".
//
// Ademas recalcula cada linea: cantidad x precio_unitario contra el importe
// declarado. En la factura 06 cada linea cierra perfecto y aun asi la factura
// esta mal, y eso se ve sumando la columna importe_declarado: da 720.000
// cuando la cabecera declara un subtotal de 702.000.
// ===========================================================================

const TOLERANCIA = 0.01;
const r2 = (n) => Math.round(n * 100) / 100;

function num(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return isFinite(v) ? v : null;
  let s = String(v).replace(/[^0-9.,-]/g, '').trim();
  if (!s) return null;
  const coma = s.lastIndexOf(',');
  const punto = s.lastIndexOf('.');
  if (coma > punto) s = s.replace(/\./g, '').replace(',', '.');
  else s = s.replace(/,/g, '');
  const n = parseFloat(s);
  return isFinite(n) ? n : null;
}

const salida = [];

for (const entrada of $input.all()) {
  const f = entrada.json ?? {};
  const items = Array.isArray(f.items) ? f.items : [];

  items.forEach((it, i) => {
    const cant = num(it.cantidad);
    const unit = num(it.precio_unitario);
    const importe = num(it.importe);

    const recalculado = (cant !== null && unit !== null) ? r2(cant * unit) : null;
    const diferencia = (recalculado !== null && importe !== null)
      ? r2(importe - recalculado)
      : null;

    let estadoItem = 'OK';
    if (importe === null) estadoItem = 'SIN_IMPORTE';
    else if (diferencia !== null && Math.abs(diferencia) > TOLERANCIA) estadoItem = 'NO_CIERRA';

    salida.push({
      json: {
        procesado_en: f.procesado_en ?? null,
        archivo: f.archivo ?? null,
        numero_factura: f.numero_factura ?? null,
        emisor: f.emisor ?? null,
        moneda: f.moneda ?? null,
        item_nro: i + 1,
        descripcion: it.descripcion ?? null,
        // cantidad y precio se guardan tal cual figuran en el documento.
        // El numero limpio va en las columnas recalculadas.
        cantidad: it.cantidad ?? null,
        precio_unitario: it.precio_unitario ?? null,
        importe_declarado: importe,
        importe_recalculado: recalculado,
        diferencia: diferencia,
        estado_item: estadoItem,
      },
    });
  });
}

return salida;

// ===========================================================================
// Arma el mensaje de Telegram. Una alerta que no dice QUE revisar y CUANTA
// plata hay en juego no sirve: se ignora a la tercera vez.
// ===========================================================================

const ICONO = { alta: '\u274c', media: '\u26a0\ufe0f' };
const salida = [];

for (const entrada of $input.all()) {
  const f = entrada.json;
  const problemas = Array.isArray(f.problemas) ? f.problemas : [];

  const plata = problemas
    .map((p) => Math.abs(Number(p.diferencia) || 0))
    .reduce((a, b) => Math.max(a, b), 0);

  let msg = '\ud83d\udea8 *Factura para revisar*\n';
  msg += '\u2500'.repeat(24) + '\n';
  msg += '\ud83d\udcc4 Archivo: `' + (f.archivo ?? 's/d') + '`\n';
  if (f.numero_factura) msg += '\ud83e\uddfe Comprobante: ' + f.numero_factura + '\n';
  if (f.emisor) msg += '\ud83c\udfe2 Emisor: ' + f.emisor + '\n';
  if (f.total_declarado !== null && f.total_declarado !== undefined) {
    msg += '\ud83d\udcb0 Total declarado: ' + (f.moneda ?? '') + ' ' + f.total_declarado + '\n';
  }
  msg += '\n*Problemas detectados (' + problemas.length + '):*\n';

  for (const p of problemas) {
    msg += (ICONO[p.severidad] ?? '\u2022') + ' *' + p.tipo + '*\n';
    msg += '   ' + p.detalle + '\n';
  }

  if (plata > 0) {
    msg += '\n\ud83d\udcb8 *Diferencia maxima: ' + (f.moneda ?? '') + ' ' + plata.toFixed(2) + '*\n';
  }

  msg += '\n\u27a1\ufe0f Se registro en la planilla con estado *' + f.estado + '*. ';
  msg += 'No avanza a pago hasta que alguien la mire.';

  salida.push({ json: { message: msg, archivo: f.archivo, estado: f.estado } });
}

return salida;
